import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.XXezeKOl.js";const h=JSON.parse('{"title":"工程师路径","description":"面向有开发经验但没做过大模型应用的工程师，约 8 周，从 API 调用到可评估、可部署的 Agent 服务。","frontmatter":{"title":"工程师路径","description":"面向有开发经验但没做过大模型应用的工程师，约 8 周，从 API 调用到可评估、可部署的 Agent 服务。"},"headers":[],"relativePath":"roadmap/engineer.md","filePath":"roadmap/engineer.md","lastUpdated":null}'),t={name:"roadmap/engineer.md"};function n(o,e,g,p,s,d){return i(),r("div",null,[...e[0]||(e[0]=[l(`<h1 id="工程师路径" tabindex="-1">工程师路径 <a class="header-anchor" href="#工程师路径" aria-label="Permalink to &quot;工程师路径&quot;">​</a></h1><p>这条路径适合有 1 年以上开发经验的工程师：熟悉至少一门语言，写过 HTTP 服务，理解异步和错误处理。你不需要补编程基础，重点是建立对模型行为的直觉，以及把 Agent 当成一个&quot;不确定的组件&quot;来做工程化。</p><p>节奏按每周 8 到 10 小时估算，约 8 周。Go / Java 开发者可以全程用自己的语言做项目，相关文章都有 [Go] [Java] 标签页，框架部分重点看 <a href="/guide/11-frameworks/go-eino">Go：Eino 与 langchaingo</a> 或 <a href="/guide/11-frameworks/java-spring-ai">Java：Spring AI 与 LangChain4j</a>。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 周       第 2 周          第 3-4 周             第 5-6 周               第 7-8 周</span></span>
<span class="line"><span>基础速通 ──▶ 模型与提示词 ──▶ Tool Calling 与   ──▶ 上下文/记忆/RAG/  ──▶  多 Agent、评估</span></span>
<span class="line"><span>                              Agent 循环            MCP/框架               与生产化</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="阶段-1-基础速通-第-1-周" tabindex="-1">阶段 1：基础速通（第 1 周） <a class="header-anchor" href="#阶段-1-基础速通-第-1-周" aria-label="Permalink to &quot;阶段 1：基础速通（第 1 周）&quot;">​</a></h2><p>目标：确认环境和基础工具链，半天到一天即可完成。</p><p>必读：</p><ul><li><a href="/guide/00-intro/what-is-agent">Agent 到底是什么</a></li><li><a href="/guide/00-intro/agent-vs-workflow">Agent、Chatbot 与 Workflow 的区别</a></li><li><a href="/guide/00-intro/capabilities">Agent 的能力边界与适用场景</a></li><li><a href="/guide/01-programming/streaming-sse">流式输出与 SSE</a></li><li><a href="/guide/01-programming/data-validation">数据校验：pydantic / struct tag / record</a></li></ul><p>可以跳过：开发环境、Python 基础、异步、HTTP 等文章，遇到不熟的点再查。</p><p>自检清单：</p><ul><li>[ ] 能说出 Agent 和固定 Workflow 各自适合什么场景</li><li>[ ] 能用自己的语言消费一个 SSE 流</li><li>[ ] 知道用什么方式把模型输出的 JSON 校验成强类型对象</li></ul><h2 id="阶段-2-大模型与提示词-第-2-周" tabindex="-1">阶段 2：大模型与提示词（第 2 周） <a class="header-anchor" href="#阶段-2-大模型与提示词-第-2-周" aria-label="Permalink to &quot;阶段 2：大模型与提示词（第 2 周）&quot;">​</a></h2><p>目标：建立对模型行为的直觉，能稳定拿到结构化输出。</p><p>必读：</p><ul><li><a href="/guide/02-llm-basics/tokens-context">Token 与上下文窗口</a></li><li><a href="/guide/02-llm-basics/sampling">采样参数：temperature、top_p</a></li><li><a href="/guide/02-llm-basics/reasoning-models">推理模型与扩展思考</a></li><li><a href="/guide/02-llm-basics/choosing-models">如何选择模型</a></li><li><a href="/guide/03-llm-api/providers">主流模型厂商 API 对比</a></li><li><a href="/guide/03-llm-api/multi-turn">多轮对话与消息结构</a></li><li><a href="/guide/03-llm-api/cost-errors">计费、限流与错误重试</a></li><li><a href="/guide/04-prompt/basics">提示词基本原则</a></li><li><a href="/guide/04-prompt/system-prompt">系统提示词与角色设计</a></li><li><a href="/guide/04-prompt/structured-output">结构化输出与 JSON Schema</a></li><li><a href="/guide/04-prompt/prompt-management">提示词版本管理与测试</a></li></ul><p>可以略读：<a href="/guide/02-llm-basics/transformer">Transformer 的直觉理解</a>、<a href="/guide/03-llm-api/first-call">第一次调用大模型</a>。</p><p>项目：<a href="/projects/01-cli-chat">01 命令行聊天助手</a>，用半天完成，重点加上流式输出和重试。</p><p>自检清单：</p><ul><li>[ ] 能估算一次请求的 Token 量，知道输入和输出 Token 分开计费</li><li>[ ] 能解释推理模型和普通模型在使用方式上的差别</li><li>[ ] 能对比至少两家厂商 API 的消息格式差异</li><li>[ ] 能用 JSON Schema 约束输出，并处理校验失败的情况</li><li>[ ] 提示词放在版本库里管理，修改后有样例可以回归</li></ul><h2 id="阶段-3-tool-calling-与-agent-循环-第-3-4-周" tabindex="-1">阶段 3：Tool Calling 与 Agent 循环（第 3-4 周） <a class="header-anchor" href="#阶段-3-tool-calling-与-agent-循环-第-3-4-周" aria-label="Permalink to &quot;阶段 3：Tool Calling 与 Agent 循环（第 3-4 周）&quot;">​</a></h2><p>目标：不借助框架写出完整的 Agent，理解每一步的消息流转。这是整条路径最重要的阶段。</p><p>必读：本阶段两个模块全部必读。</p><ul><li><a href="/guide/05-tool-calling/concept">工具调用原理</a>、<a href="/guide/05-tool-calling/first-tool">实现第一个工具</a>、<a href="/guide/05-tool-calling/tool-design">工具设计原则</a>、<a href="/guide/05-tool-calling/parallel-tools">并行工具调用</a>、<a href="/guide/05-tool-calling/error-handling">工具错误处理与重试</a></li><li><a href="/guide/06-agent-loop/react">ReAct：推理与行动</a>、<a href="/guide/06-agent-loop/handwritten-agent">不用框架手写 Agent</a>、<a href="/guide/06-agent-loop/plan-execute">Plan-and-Execute</a>、<a href="/guide/06-agent-loop/reflection">Reflection 自我反思</a>、<a href="/guide/06-agent-loop/stop-budget">终止条件、步数与预算控制</a></li></ul><p>选读论文：<a href="/papers/react">ReAct</a>、<a href="/papers/reflexion">Reflexion</a>。</p><p>项目：<a href="/projects/02-tool-agent">02 天气日程工具 Agent</a> 和 <a href="/projects/03-react-agent">03 手写 ReAct Agent</a>。</p><p>自检清单：</p><ul><li>[ ] 能手写 Agent 主循环，并说清每一轮消息列表里新增了什么</li><li>[ ] 工具描述写得足够清楚，模型很少选错工具或传错参数</li><li>[ ] 能处理并行工具调用，并按 ID 把结果对应回去</li><li>[ ] Agent 有最大步数、Token 预算和超时三重保护</li><li>[ ] 能说出 ReAct 和 Plan-and-Execute 各自的优缺点</li></ul><h2 id="阶段-4-上下文、记忆、rag、mcp-与框架-第-5-6-周" tabindex="-1">阶段 4：上下文、记忆、RAG、MCP 与框架（第 5-6 周） <a class="header-anchor" href="#阶段-4-上下文、记忆、rag、mcp-与框架-第-5-6-周" aria-label="Permalink to &quot;阶段 4：上下文、记忆、RAG、MCP 与框架（第 5-6 周）&quot;">​</a></h2><p>目标：解决&quot;Agent 拿不到正确信息&quot;的问题，并能在框架和手写之间做取舍。</p><p>必读：</p><ul><li><a href="/guide/07-context-engineering/overview">什么是上下文工程</a>、<a href="/guide/07-context-engineering/window-management">上下文窗口管理</a>、<a href="/guide/07-context-engineering/compression">压缩与摘要</a>、<a href="/guide/07-context-engineering/prompt-caching">Prompt Caching</a></li><li><a href="/guide/08-memory/memory-types">记忆的分类</a>、<a href="/guide/08-memory/memory-strategy">记忆读写策略与方案对比</a></li><li><a href="/guide/02-llm-basics/embeddings">Embedding 与向量语义</a></li><li><a href="/guide/09-rag/overview">RAG 全景</a>、<a href="/guide/09-rag/chunking">文档解析与切分</a>、<a href="/guide/09-rag/vector-db">向量数据库</a>、<a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a>、<a href="/guide/09-rag/rag-eval">RAG 评估</a></li><li><a href="/guide/10-mcp/mcp-overview">MCP 架构与核心概念</a>、<a href="/guide/10-mcp/mcp-server">开发一个 MCP Server</a>、<a href="/guide/10-mcp/mcp-client">在应用中接入 MCP</a></li><li><a href="/guide/11-frameworks/overview">框架全景与选型</a>，再根据语言选一篇：<a href="/guide/11-frameworks/langgraph">LangGraph</a>、<a href="/guide/11-frameworks/go-eino">Go：Eino 与 langchaingo</a> 或 <a href="/guide/11-frameworks/java-spring-ai">Java：Spring AI 与 LangChain4j</a></li></ul><p>可以略读：<a href="/guide/08-memory/short-term">短期记忆与会话管理</a>、<a href="/guide/08-memory/long-term">长期记忆与用户画像</a>、<a href="/guide/09-rag/advanced-rag">GraphRAG 与 Agentic RAG</a>、<a href="/guide/10-mcp/a2a">A2A</a>、<a href="/guide/11-frameworks/low-code">低代码平台</a>。</p><p>项目：<a href="/projects/04-pdf-rag">04 个人 PDF 知识库</a> 和 <a href="/projects/05-mcp-server">05 开发自己的 MCP Server</a>，时间允许再做 <a href="/projects/06-research-agent">06 网页研究员 Agent</a>。</p><p>自检清单：</p><ul><li>[ ] 长对话时有明确的截断或压缩策略，并知道它对 Prompt Caching 的影响</li><li>[ ] 能根据数据特点选择切分策略，并说明理由</li><li>[ ] 能解释为什么要做混合检索和重排</li><li>[ ] 能分别衡量 RAG 的检索质量和生成质量</li><li>[ ] 能把一个已有的内部 API 包装成 MCP Server</li><li>[ ] 能说出在你的场景里用框架的收益和代价</li></ul><h2 id="阶段-5-多-agent、评估与生产化-第-7-8-周" tabindex="-1">阶段 5：多 Agent、评估与生产化（第 7-8 周） <a class="header-anchor" href="#阶段-5-多-agent、评估与生产化-第-7-8-周" aria-label="Permalink to &quot;阶段 5：多 Agent、评估与生产化（第 7-8 周）&quot;">​</a></h2><p>目标：把 Agent 变成可以上线、可以持续迭代的服务。</p><p>必读：</p><ul><li><a href="/guide/14-evaluation/why-evals">为什么评估是第一优先级</a>、<a href="/guide/14-evaluation/eval-design">评估集与指标设计</a>、<a href="/guide/14-evaluation/llm-judge">LLM-as-Judge</a>、<a href="/guide/14-evaluation/observability">轨迹追踪与可观测性</a>、<a href="/guide/14-evaluation/regression">回归测试与持续评估</a></li><li><a href="/guide/15-production/prompt-injection">Prompt 注入与防护</a>、<a href="/guide/15-production/permissions-hitl">权限控制与人在环路</a>、<a href="/guide/15-production/guardrails">护栏与内容安全</a>、<a href="/guide/15-production/cost-optimization">成本与延迟优化</a>、<a href="/guide/15-production/serving">服务化：FastAPI / Gin / Spring Boot</a>、<a href="/guide/15-production/deployment">部署、监控与运维</a></li><li><a href="/guide/12-multi-agent/why-multi-agent">为什么需要多 Agent</a>、<a href="/guide/12-multi-agent/patterns">编排模式</a>、<a href="/guide/12-multi-agent/pitfalls">多 Agent 的坑与成本控制</a></li><li><a href="/guide/13-coding-agent/sandbox">沙箱与代码执行安全</a></li></ul><p>可以略读：<a href="/guide/12-multi-agent/state-sharing">状态共享与通信</a>、模块 13 中的其他文章（按业务需要再读）。</p><p>项目：<a href="/projects/08-code-review">08 代码审查 Agent</a> 或 <a href="/projects/09-agent-workbench">09 全栈 Agent 工作台</a>，最后挑战 <a href="/projects/10-enterprise-assistant">10 毕业项目：企业知识助手</a>。</p><p>自检清单：</p><ul><li>[ ] 有一个至少 50 条用例的评估集，每次改提示词或换模型都会跑</li><li>[ ] 每次请求都有完整的轨迹记录，能定位是哪一步出错</li><li>[ ] 能防御间接 Prompt 注入，高风险操作需要人工确认</li><li>[ ] Agent 以 API 服务形式部署，支持流式输出、超时和限流</li><li>[ ] 能说出单 Agent 改为多 Agent 的判断依据和额外成本</li><li>[ ] 能给出一次请求的成本和延迟构成，并提出至少两种优化手段</li></ul><p>完成后，如果你开始负责技术选型或团队落地，继续看 <a href="/roadmap/architect">架构师路径</a>。面试准备可以看 <a href="/interview/">面试题</a>。</p>`,44)])])}const c=a(t,[["render",n]]);export{h as __pageData,c as default};
